select is((select count(*) from public.orders where id='00000000-0000-4000-8000-000000000523'),0::bigint,'Una seña inválida revierte la nota completa');
select throws_ok($$select public.record_payment('00000000-0000-4000-8000-000000000531','00000000-0000-4000-8000-000000000521',30,'1901-01-15','cash','')$$,'42501',null,'Diseño no puede registrar cobros posteriores sin Finanzas');
