set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000502';
select lives_ok($$select public.record_payment('00000000-0000-4000-8000-000000000531','00000000-0000-4000-8000-000000000521',30,'1901-01-15','cash','Pago parcial')$$,'Registra un cobro parcial');
select is((public.order_money('00000000-0000-4000-8000-000000000521')->>'balance')::numeric,30::numeric,'El saldo incluye todos los cobros');
select public.record_payment('00000000-0000-4000-8000-000000000531','00000000-0000-4000-8000-000000000521',30,'1901-01-15','cash','');
select is((public.order_money('00000000-0000-4000-8000-000000000521')->>'paid')::numeric,70::numeric,'Reintentar un cobro no lo duplica');
select throws_ok($$select public.record_payment('00000000-0000-4000-8000-000000000532','00000000-0000-4000-8000-000000000521',31,'1901-01-15','cash','')$$,'23514',null,'No permite cobrar más que el saldo');
select lives_ok($$select public.record_expense('00000000-0000-4000-8000-000000000533',20,'1901-01-15','cash','Compra de papel')$$,'Registra un egreso pagado');
select public.record_expense('00000000-0000-4000-8000-000000000533',20,'1901-01-15','cash','Compra de papel');
select is((public.finance_month('1901-01-01')->>'income')::numeric,70::numeric,'El mes cuenta señas y pagos una sola vez');
select is((public.finance_month('1901-01-01')->>'expenses')::numeric,20::numeric,'El mes cuenta egresos sin duplicar reintentos');
select is((public.finance_month('1901-01-01')->>'net')::numeric,50::numeric,'La diferencia usa cobrado menos pagado');
