update public.orders set created_at=now()-interval '15 days'+interval '1 second' where id='00000000-0000-4000-8000-000000000521';
set local role authenticated;
select is((public.order_money('00000000-0000-4000-8000-000000000521')->>'overdue')::boolean,false,'No avisa antes de cumplir los 15 días');
