select lives_ok($$select public.create_order_from_quote('00000000-0000-4000-8000-000000000541',2,null,null,null,'{"amount":"25","paid_on":"1901-01-15","method":"cash"}')$$,'La conversión desde presupuesto también admite seña');
select is((select (public.order_money(id)->>'deposit')::numeric from public.orders where quote_id='00000000-0000-4000-8000-000000000541'),25::numeric,'La nota convertida conserva su seña');
select public.create_order_from_quote('00000000-0000-4000-8000-000000000541',2,null,null,null,'{"amount":"25","paid_on":"1901-01-15","method":"cash"}');
select is((select (public.order_money(id)->>'paid')::numeric from public.orders where quote_id='00000000-0000-4000-8000-000000000541'),25::numeric,'Reintentar la conversión no duplica la seña');
